  if (value === true) return 'True';
  if (value === false) return 'False';
  return String(value);
}

/** Python `repr()` for the handful of values this port has to render. */
export function pyRepr(value) {
  if (value === null || value === undefined) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (typeof value === 'string') {
    const escaped = value.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    return `'${escaped}'`;
  }
  return String(value);
}

/**
 * Greedy word wrap equivalent to `textwrap.wrap(text, width)` for the
 * single-spaced, hyphen-free help strings this port renders: whitespace runs
 * collapse to one space and words are never broken.
 */
export function wrap(text, width) {
  const words = text.split(/\s+/u).filter(w => w.length > 0);
  if (words.length === 0) return [];
  const lines = [];
  let line = words[0];
  for (const word of words.slice(1)) {
    if (pyLen(line) + 1 + pyLen(word) <= width) {
      line += ` ${word}`;
    } else {
      lines.push(line);
      line = word;
    }
  }
  lines.push(line);
  return lines;
}

/**
 * Reproduces the crash report the reference build writes to stderr when
 * `schedule.Job.at()` rejects its argument.
 *
 * Run from the directory containing `test4.py`, the frozen executable prints:
 *
 *     Traceback (most recent call last):
 *       File "test4.py", line 10, in <module>
 *         job = schedule.every().monday.at(args.a)  # 创建每周一特定时间作业
 *               ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
 *       File "schedule/__init__.py", line 514, in at
 *     schedule.ScheduleValueError: Invalid time format for a daily job (valid format is HH:MM(:SS)?)
 *     [PYI-197:ERROR] Failed to execute script 'test4' due to unhandled exception!
 *
 * Three behaviours of that output are reproduced deliberately:
 *
 *   - The echoed source line and its `^^^^` anchors are only present when
 *     `test4.py` can actually be read from the current directory — see
 *     `../py/linecache.mjs`. The library frame never shows source, because the
 *     bundle ships no `.py` files for dependencies.
 *   - The anchor geometry comes from column offsets baked into the code object
 *     at build time (bytes 6..40 of line 10), mapped onto whatever line the
 *     lookup returned and measured in display columns. A shorter line clips the
 *     anchors; an indented line shifts them left; wide CJK characters push them
 *     right. When the anchors would span the whole stripped line, CPython omits
 *     the anchor row entirely.
 *   - The number in the `PYI-` tag is the process id, so it differs on every
 *     run of the reference too. `process.pid` is used for the same reason, which
 *     means this line is inherently not byte-comparable between runs.
 */
import { getline } from '../py/linecache.mjs';
import { pyStrip, pyLStrip } from '../py/whitespace.mjs';
import { displayWidth, byteOffsetToCharOffset } from '../py/eastasian.mjs';

/** Indentation CPython uses for a frame's `File "..."` line. */
const FRAME_INDENT = '  ';
/** Indentation CPython uses for the echoed source line. */
const SOURCE_INDENT = '    ';

/**
 * Describe a traceback frame.
 *
 * @param {string} file      value rendered inside `File "..."`
 * @param {number} line      line number
 * @param {string} func      enclosing function name, e.g. `<module>`
 * @param {?number} colno    start byte column of the failing expression
 * @param {?number} endColno end byte column of the failing expression
 */
export function frame(file, line, func, colno = null, endColno = null) {
  return { file, line, func, colno, endColno };
}

/**
 * Build the echoed source line plus anchor row for one frame, mirroring
 * `traceback.StackSummary.format_frame_summary`.
 */
function renderSource({ file, line, colno, endColno }) {
  const original = getline(file, line);
  const stripped = pyStrip(original);
  if (!stripped) return '';

  let out = `${SOURCE_INDENT}${stripped}\n`;
  if (colno === null || endColno === null) return out;

  // Leading whitespace that `strip()` removed, so anchors can shift left.
  const strippedCharacters = Array.from(original).length
    - Array.from(pyLStrip(original)).length;

  const startChar = byteOffsetToCharOffset(original, colno);
  const endChar = byteOffsetToCharOffset(original, endColno);
  const startColumn = displayWidth(Array.from(original).slice(0, startChar).join(''));
  const endColumn = displayWidth(Array.from(original).slice(0, endChar).join(''));

  // CPython omits the anchors when they would cover the entire line.
  if (endColumn - startColumn >= displayWidth(stripped)) return out;

  const anchorStart = SOURCE_INDENT.length + startColumn - strippedCharacters;
  const anchorEnd = SOURCE_INDENT.length + endColumn - strippedCharacters;
  const leading = Math.max(0, anchorStart);
  const carets = Math.max(0, anchorEnd - leading);
  out += `${' '.repeat(leading)}${'^'.repeat(carets)}\n`;
  return out;
}

function renderFrame(f) {
  return `${FRAME_INDENT}File "${f.file}", line ${f.line}, in ${f.func}\n`
    + renderSource(f);
}

/**
 * Render the full stderr payload for an unhandled exception.
 *
 * @param {Array} frames     outermost frame first, as CPython prints them
 * @param {string} pyName    dotted exception name
 * @param {string} message   exception message
 * @param {string} scriptName name quoted on the PyInstaller line
 */
export function formatTraceback(frames, pyName, message, scriptName) {
  const body = frames.map(renderFrame).join('');
  return `Traceback (most recent call last):\n${body}${pyName}: ${message}\n`
    + `[PYI-${process.pid}:ERROR] Failed to execute script '${scriptName}' `
    + 'due to unhandled exception!\n';
}

/** Write a rendered traceback to stderr. */
export function printTraceback(frames, pyName, message, scriptName) {
  process.stderr.write(formatTraceback(frames, pyName, message, scriptName));
}
/**
 * A stand-in for Python's `linecache`, which is what lets a traceback echo the
 * offending source line.
 *
 * This is not incidental detail — it is the reason the reference build's stderr
 * changes with the working directory. The frozen executable records the frame
 * filename as the bare relative path `test4.py`, and `linecache` resolves it
 * against the current directory. Run from the folder holding `test4.py` you get
 *
 *       File "test4.py", line 10, in <module>
 *         job = schedule.every().monday.at(args.a)  # 创建每周一特定时间作业
 *               ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
 *
 * and run from anywhere else you get only the `File "test4.py"` line, because
 * PyInstaller bundles no `.py` sources. A file that merely happens to be named
 * `test4.py` is used just as readily — the lookup is by name, not by content.
 */
import fs from 'node:fs';

/** `linecache.cache` — parsed file contents, keyed by filename. */
const cache = new Map();

function readLines(filename) {
  if (cache.has(filename)) return cache.get(filename);
  let lines = null;
  try {
    const text = fs.readFileSync(filename, 'utf8');
    // Keep line terminators, as `readlines()` does.
    lines = text.length === 0 ? [] : text.split(/(?<=\n)/u);
  } catch {
    // Unreadable or missing: linecache yields '' rather than raising.
    lines = null;
  }
  cache.set(filename, lines);
  return lines;
}

/**
 * `linecache.getline(filename, lineno)` — the 1-indexed line including its
 * trailing newline, or `''` when it cannot be produced.
 */
export function getline(filename, lineno) {
  const lines = readLines(filename);
  if (lines === null) return '';
  if (lineno < 1 || lineno > lines.length) return '';
  return lines[lineno - 1];
}

/** `linecache.clearcache()`. */
export function clearcache() {
  cache.clear();
}

