/* Fast parallel differential harness. Cases are read from a JSON file:
   [{argv:[...], cwd?:'...', env?:{...}}, ...]  or  [[argv...], ...] */
import { spawn } from 'node:child_process';
import fs from 'node:fs';

const REF = '/tmp/fz/test4.mjs';   // reference copy named test4.mjs
const JS = '/output/test4.mjs';
const DEFAULT_CWD = process.argv[3] || '/workspace/dataset';
const CONC = Number(process.env.CONC || 24);

function norm(s) {
  return s.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
}

function run(cmd, args, argv, cwd, env) {
  return new Promise((resolve) => {
    const p = spawn(cmd, [...args, ...argv], {
      cwd, env: { ...process.env, ...(env || {}) },
    });
    const out = []; const err = [];
    p.stdout.on('data', d => out.push(d));
    p.stderr.on('data', d => err.push(d));
    p.on('error', e => resolve({ code: -999, out: '', err: String(e) }));
    p.on('close', (code, sig) => resolve({
      code: sig ? `sig:${sig}` : code,
      out: Buffer.concat(out).toString('utf8'),
      err: Buffer.concat(err).toString('utf8'),
    }));
  });
}

const raw = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const CASES = raw.map(c => Array.isArray(c) ? { argv: c } : c);

let pass = 0;
const fails = [];
let idx = 0;

async function worker() {
  for (;;) {
    const i = idx++;
    if (i >= CASES.length) return;
    const c = CASES[i];
    const cwd = c.cwd || DEFAULT_CWD;
    const [a, b] = await Promise.all([
      run(REF, [], c.argv, cwd, c.env),
      run('node', [JS], c.argv, cwd, c.env),
    ]);
    const problems = [];
    if (a.code !== b.code) problems.push(`exit ${a.code} vs ${b.code}`);
    if (norm(a.out) !== norm(b.out)) problems.push(`stdout\n  py=${JSON.stringify(norm(a.out))}\n  js=${JSON.stringify(norm(b.out))}`);
    if (norm(a.err) !== norm(b.err)) problems.push(`stderr\n  py=${JSON.stringify(norm(a.err))}\n  js=${JSON.stringify(norm(b.err))}`);
    if (problems.length === 0) pass++;
    else fails.push({ i, c, problems });
  }
}

